package com.futahua.papers.mobile;
import android.app.*;import android.os.*;import android.database.*;import android.database.sqlite.*;import android.provider.MediaStore;import org.json.*;import java.io.*;import java.util.*;

/** Read-only storage census and disposable engine benchmark; no product UI changes. */
public final class SearchResearchCheck extends Instrumentation {
  @Override public void onCreate(Bundle args){start();}
  static String fold(String text){return java.text.Normalizer.normalize(text,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").replace('đ','d').replace('Đ','D').toLowerCase(Locale.ROOT);}
  static String grams(String text){Set<String> tokens=new LinkedHashSet<>();for(int i=0;i+3<=text.length();i++){StringBuilder t=new StringBuilder("g");for(char c:text.substring(i,i+3).toCharArray()){String hex=Integer.toHexString(c);for(int n=hex.length();n<4;n++)t.append('0');t.append(hex);}tokens.add(t.toString());}return String.join(" ",tokens);}
  static JSONObject query(SQLiteDatabase db,String pattern,boolean trigram)throws Exception{String q=fold(pattern);long started=System.nanoTime();int count=0;String sql=trigram?"SELECT count(*) FROM files WHERE rowid IN(SELECT rowid FROM grams WHERE grams MATCH ?) AND instr(fold,?)>0":"SELECT count(*) FROM files WHERE instr(fold,?)>0";String[] args=trigram?new String[]{grams(q),q}:new String[]{q};try(Cursor cursor=db.rawQuery(sql,args)){if(cursor.moveToFirst())count=cursor.getInt(0);}return new JSONObject().put("query",pattern).put("count",count).put("ms",(System.nanoTime()-started)/1e6);}
  @Override public void onStart(){Bundle result=new Bundle();File index=new File(getTargetContext().getCacheDir(),"search-research-"+UUID.randomUUID()+".db");SQLiteDatabase db=null;try{
    JSONObject report=new JSONObject();db=SQLiteDatabase.openOrCreateDatabase(index,null);try(Cursor c=db.rawQuery("SELECT sqlite_version()",null)){c.moveToFirst();report.put("sqlite",c.getString(0));}
    try{db.execSQL("CREATE VIRTUAL TABLE probe USING fts5(name,tokenize='trigram')");report.put("fts5Trigram",true);}catch(Exception e){report.put("fts5Trigram",false).put("fts5Error",e.getMessage());}
    db.execSQL("CREATE TABLE files(path TEXT,name TEXT,fold TEXT,kind INTEGER)");db.execSQL("CREATE INDEX names ON files(name)");db.execSQL("CREATE VIRTUAL TABLE grams USING fts4(tokens)");
    ArrayDeque<File> pending=new ArrayDeque<>(PhoneStorage.roots());Set<String> paths=new HashSet<>();int folders=0,files=0,unreadable=0;long started=System.nanoTime(),deadline=SystemClock.elapsedRealtime()+60000;boolean limited=false;
    SQLiteStatement insert=db.compileStatement("INSERT INTO files(path,name,fold,kind) VALUES(?,?,?,?)");db.beginTransaction();
    while(!pending.isEmpty()){if(paths.size()>=100000||SystemClock.elapsedRealtime()>deadline){limited=true;break;}File f=pending.pop();if(java.nio.file.Files.isSymbolicLink(f.toPath()))continue;String path=f.getCanonicalPath();if(!paths.add(path))continue;if(f.isDirectory()){folders++;File[] children=f.listFiles();if(children==null){unreadable++;continue;}for(File child:children)pending.push(child);}else files++;insert.bindString(1,path);insert.bindString(2,f.getName());insert.bindString(3,fold(path));insert.bindLong(4,f.isDirectory()?1:0);insert.executeInsert();}
    db.setTransactionSuccessful();db.endTransaction();report.put("scanMs",(System.nanoTime()-started)/1e6).put("files",files).put("folders",folders).put("unreadableFolders",unreadable).put("limited",limited).put("scanRows",DatabaseUtils.longForQuery(db,"SELECT count(*) FROM files",null));
    long begin=System.nanoTime();int media=0,overlap=0;try(Cursor c=getTargetContext().getContentResolver().query(MediaStore.Files.getContentUri("external"),new String[]{"_data"},null,null,null)){if(c!=null)while(c.moveToNext()){media++;if(paths.contains(c.getString(0)))overlap++;}}catch(Exception e){report.put("mediaError",e.toString());}report.put("mediaRows",media).put("mediaOverlap",overlap).put("mediaQueryMs",(System.nanoTime()-begin)/1e6);
    JSONArray scanQueries=new JSONArray();String[] queries={"pdf","download","2026","png","ilan","bailan","anh","q"};for(String q:queries)scanQueries.put(query(db,q,false));report.put("scanQueries",scanQueries);
    begin=System.nanoTime();db.beginTransaction();SQLiteStatement add=db.compileStatement("INSERT INTO grams(rowid,tokens) VALUES(?,?)");try(Cursor c=db.rawQuery("SELECT rowid,fold FROM files",null)){while(c.moveToNext()){add.bindLong(1,c.getLong(0));add.bindString(2,grams(c.getString(1)));add.executeInsert();}}db.setTransactionSuccessful();db.endTransaction();report.put("trigramBuildMs",(System.nanoTime()-begin)/1e6);
    JSONArray gramQueries=new JSONArray();for(String q:queries)if(q.length()>=3)gramQueries.put(query(db,q,true));report.put("trigramQueries",gramQueries).put("indexBytes",index.length());
    try(FileOutputStream out=getTargetContext().openFileOutput("phone-search-research.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("result",report.toString());finish(Activity.RESULT_OK,result);
  }catch(Exception e){result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{if(db!=null)db.close();index.delete();new File(index.getPath()+"-journal").delete();}}
}
